package com.bookrush.publisherservice.api;
import java.security.Principal; import java.util.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import com.bookrush.publisherservice.BehaviorEventPublisher;
@RestController @RequestMapping("/api/v1/publisher") public class PublisherController { private final JdbcTemplate jdbc; private final com.bookrush.publisherservice.PublisherIngestionClient ingestion; private final BehaviorEventPublisher behavior; public PublisherController(JdbcTemplate jdbc, com.bookrush.publisherservice.PublisherIngestionClient ingestion, BehaviorEventPublisher behavior){this.jdbc=jdbc;this.ingestion=ingestion;this.behavior=behavior;} private String s(Principal p){if(p==null||p.getName()==null||p.getName().isBlank()) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"authentication required"); return p.getName();} private void membership(String subject){jdbc.update("INSERT INTO publisher.membership(subject_key) VALUES (?) ON CONFLICT DO NOTHING",subject); if(jdbc.queryForObject("SELECT status FROM publisher.membership WHERE subject_key=?",String.class,subject).equals("SUSPENDED")) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"publisher membership suspended");} private void operator(Authentication a){if(a==null||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_platform-admins")||x.getAuthority().equals("ROLE_operators")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"operator permission required");} public record Submission(@NotBlank @Size(max=300) String title, UUID catalogBookId, String sourceCode, String sourceExternalId){}
 @PostMapping("/submissions") public Object create(@Valid @RequestBody Submission req,Principal p,HttpServletRequest request){String subject=s(p);membership(subject);UUID id=UUID.randomUUID();jdbc.update("insert into publisher.submission(id,subject_key,title,catalog_book_id,source_code,source_external_id) values(?,?,?,?,?,?)",id,subject,req.title(),req.catalogBookId(),req.sourceCode(),req.sourceExternalId());behavior.publish("PUBLISHER_SUBMISSION_CREATED",req.catalogBookId(),Map.of("submissionId",id),request.getHeader("Authorization"));return Map.of("id",id,"title",req.title(),"status","DRAFT");}
 @PostMapping("/submissions/{id}/submit") public Object submit(@PathVariable UUID id,Principal p,HttpServletRequest request){String subject=s(p);int n=jdbc.update("update publisher.submission set status='SUBMITTED',updated_at=now() where id=? and subject_key=? and status in ('DRAFT','UPLOADED')",id,subject);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"draft not found");var uploads=jdbc.queryForList("select object_key,content_type,sha256 from publisher.staged_upload where submission_id=? and subject_key=? and status='FINALIZED' order by finalized_at desc limit 1",id,subject);if(!uploads.isEmpty()){var upload=uploads.getFirst();ingestion.process(id, title(id,subject),String.valueOf(upload.get("object_key")),"books-staging",String.valueOf(upload.get("content_type")),String.valueOf(upload.get("sha256")));jdbc.update("update publisher.submission set status='PROCESSING',updated_at=now() where id=? and subject_key=?",id,subject);behavior.publish("PUBLISHER_SUBMISSION_SUBMITTED",null,Map.of("submissionId",id,"status","PROCESSING"),request.getHeader("Authorization"));return Map.of("id",id,"status","PROCESSING");}behavior.publish("PUBLISHER_SUBMISSION_SUBMITTED",null,Map.of("submissionId",id,"status","SUBMITTED"),request.getHeader("Authorization"));return Map.of("id",id,"status","SUBMITTED");}
 private String title(UUID id,String subject){return jdbc.queryForObject("select title from publisher.submission where id=? and subject_key=?",String.class,id,subject);}
 @GetMapping("/submissions") public Object list(Principal p){return jdbc.queryForList("select id,title,status,catalog_book_id,source_code,source_external_id,ingestion_job_id,linked_at,created_at,updated_at from publisher.submission where subject_key=? order by created_at desc",s(p));}
 @GetMapping("/submissions/{id}") public Object get(@PathVariable UUID id,Principal p){var rows=jdbc.queryForList("select id,title,status,catalog_book_id,source_code,source_external_id,ingestion_job_id,linked_at,created_at,updated_at from publisher.submission where id=? and subject_key=?",id,s(p)); if(rows.isEmpty()) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"submission not found"); return rows.getFirst();}
 @GetMapping("/submissions/{id}/reviews") public Object reviewHistory(@PathVariable UUID id,Principal p){String subject=s(p);if(jdbc.queryForObject("select count(*) from publisher.submission where id=? and subject_key=?",Integer.class,id,subject)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"submission not found");return jdbc.queryForList("select id,status,reviewer_subject_key,reason_code,notes,created_at from publisher.publication_review where submission_id=? order by created_at desc",id);}
 @PostMapping("/submissions/{id}/withdraw") public Object withdraw(@PathVariable UUID id,Principal p,HttpServletRequest request){String subject=s(p);int updated=jdbc.update("update publisher.published_work set status='WITHDRAWN',withdrawn_at=now() where submission_id=? and publisher_subject_key=? and status='PUBLISHED'",id,subject);if(updated==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"published submission not found");jdbc.update("update publisher.submission set status='WITHDRAWN',updated_at=now() where id=? and subject_key=?",id,subject);behavior.publish("PUBLISHER_WORK_WITHDRAWN",null,Map.of("submissionId",id),request.getHeader("Authorization"));return Map.of("submissionId",id,"status","WITHDRAWN");}
 public record Metadata(String synopsis, String language, String isbn, String publisherName, List<String> keywords) {}
 @PutMapping("/submissions/{id}/metadata") public Object metadata(@PathVariable UUID id,@RequestBody Metadata req,Principal p){String subject=s(p);membership(subject);String keywords=new com.fasterxml.jackson.databind.ObjectMapper().valueToTree(req.keywords()==null?List.of():req.keywords()).toString();int n=jdbc.update("INSERT INTO publisher.submission_metadata(submission_id,synopsis,language,isbn,publisher_name,keywords,updated_at) VALUES (?,?,?,?,?,?::jsonb,now()) ON CONFLICT (submission_id) DO UPDATE SET synopsis=excluded.synopsis,language=excluded.language,isbn=excluded.isbn,publisher_name=excluded.publisher_name,keywords=excluded.keywords,updated_at=now()",id,req.synopsis(),req.language(),req.isbn(),req.publisherName(),keywords);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"submission not found");return Map.of("submissionId",id,"updated",true);}
 public record Rights(String rightType,String territory,String evidenceReference) {}
 @PostMapping("/submissions/{id}/rights") public Object rights(@PathVariable UUID id,@Valid @RequestBody Rights req,Principal p){String subject=s(p);membership(subject);UUID rightId=UUID.randomUUID();jdbc.update("INSERT INTO publisher.rights_attestation(id,submission_id,right_type,territory,evidence_reference,affirmed_by_subject) VALUES (?,?,?,?,?,?) ON CONFLICT (submission_id,right_type,territory) DO UPDATE SET evidence_reference=excluded.evidence_reference,affirmed_by_subject=excluded.affirmed_by_subject,affirmed_at=now()",rightId,id,req.rightType(),req.territory()==null?"GLOBAL":req.territory(),req.evidenceReference(),subject);return Map.of("submissionId",id,"rightType",req.rightType(),"affirmed",true);}
 @GetMapping("/review") public Object review(Principal p,Authentication a){operator(a);s(p);return jdbc.queryForList("SELECT r.id,r.submission_id,s.title,r.status,r.reviewer_subject_key,r.reason_code,r.notes,r.created_at FROM publisher.publication_review r JOIN publisher.submission s ON s.id=r.submission_id WHERE r.status='PENDING' ORDER BY r.created_at");}
 public record Review(String status,String reasonCode,String notes) {}
 @PostMapping("/submissions/{id}/review") public Object review(@PathVariable UUID id,@RequestBody Review req,Principal p,Authentication a){operator(a);String reviewer=s(p);if(!Set.of("APPROVED","REJECTED","CHANGES_REQUESTED").contains(req.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"unsupported review status");UUID reviewId=UUID.randomUUID();jdbc.update("INSERT INTO publisher.publication_review(id,submission_id,status,reviewer_subject_key,reason_code,notes) VALUES (?,?,?,?,?,?)",reviewId,id,req.status(),reviewer,req.reasonCode(),req.notes());String next=req.status().equals("APPROVED")?"PUBLISHED":req.status().equals("REJECTED")?"REJECTED":"CHANGES_REQUESTED";jdbc.update("UPDATE publisher.submission SET status=?,updated_at=now() WHERE id=?",next,id);if(req.status().equals("APPROVED")){var row=jdbc.queryForMap("SELECT subject_key,catalog_book_id FROM publisher.submission WHERE id=?",id);jdbc.update("INSERT INTO publisher.published_work(id,submission_id,book_id,publisher_subject_key) VALUES (?,?,?,?) ON CONFLICT (submission_id) DO UPDATE SET status='PUBLISHED',withdrawn_at=NULL",UUID.randomUUID(),id,row.get("catalog_book_id"),row.get("subject_key"));}return Map.of("reviewId",reviewId,"status",req.status());}
 @GetMapping("/membership") public Object membership(Principal p){String subject=s(p);membership(subject);return jdbc.queryForMap("SELECT subject_key,status,display_name,created_at,updated_at FROM publisher.membership WHERE subject_key=?",subject);}
}
